    if not order:
        return {'status': 'error', 'msg': 'no order'}

    if 'items' not in order:
        return {'status': 'error', 'msg': 'missing items'}

    if not order['items']:
        return {'status': 'error', 'msg': 'no items'}

    total = _calculate_total(order['items'])

    if total <= 0:
        return {'status': 'error', 'msg': 'empty cart'}

